#!/usr/bin/env node
// Drift check for README.md's "See it run" fenced block, which claims to be
// "real CLI output from examples/application, not a mockup" (see the
// sentence right after the fenced block). Nothing enforced that claim: the
// example's own committed docs/manifest are golden-regenerated by
// `scripts/update-example-goldens.mjs`, but that script never looks at
// README.md, so the day-count and any other value baked into the README's
// prose block could rot silently (this happened once already -- an "expired
// 9d ago" stuck in the README long after the real figure had moved on).
//
// This script re-runs examples/application's own doc-generation command in
// an isolated temp copy (same "copy + symlink node_modules" approach as
// check-api-report.mjs's temp-dir diff, so nothing in the real examples/
// application working tree is touched), extracts the two sections of CLI
// stdout whose values are date-sensitive (the "expiring soon or already
// expired" and "unconsumed owned variable(s)" lists), and fails with a
// diff if the README's fenced block doesn't say the same thing.
//
// Deliberately narrow: it only compares those two sections, not the whole
// fenced block. The "Wrote manifest:"/"Wrote docs:"/"Wrote dependency
// ownership report:" lines are intentionally relativized in the README for
// readability (real stdout prints the absolute, checkout-dependent path),
// so comparing them verbatim would either force absolute paths into the
// README or make this check spuriously fail on every machine/CI runner.
//
// examples/application is its own npm project with its own node_modules,
// installed by CI's `examples` job, not by the root `npm ci` (see
// test/examples/support.ts's docstring). This mirrors that same convention:
// it skips gracefully instead of failing when examples/application isn't
// installed, which is what makes it safe to sit in `npm run verify`/
// `precommit` (run on a checkout that never installed examples/) as well as
// CI's `examples` job (which does, and where this check is meant to bite).
//
// Dependency-free (Node builtins only) -- dev/CI tooling, never shipped.

import { execFileSync } from "node:child_process"
import {
  cpSync,
  existsSync,
  mkdtempSync,
  mkdirSync,
  readFileSync,
  rmSync,
  symlinkSync,
} from "node:fs"
import { tmpdir } from "node:os"
import path from "node:path"
import { fileURLToPath } from "node:url"

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..")
const exampleDir = path.join(root, "examples/application")
const readmePath = path.join(root, "README.md")

if (!existsSync(path.join(exampleDir, "node_modules"))) {
  process.stdout.write(
    "[skip] examples/application: node_modules not installed (run `npm install` in examples/application first, or rely on CI's `examples` job, which does).\n",
  )
  process.exit(0)
}

// The exact invocation README.md's "See it run" fenced block shows -- kept
// as a single source of truth here so a future change to either the shown
// command or its flags can't quietly drift the two apart.
const CLI_ARGS = [
  "--include",
  "src/env.ts",
  "--location",
  "src/generated/env.manifest.ts",
  "--docs",
  "docs/ENVIRONMENT.md",
  "--ownership",
  "docs/OWNERSHIP.md",
]

const SECTION_HEADERS = [
  /^\d+ variable\(s\)\/contract\(s\) expiring soon or already expired:$/,
  /^\d+ unconsumed owned variable\(s\):$/,
]

/**
 * Pulls out each `SECTION_HEADERS` block (its header line plus every
 * following non-blank "  - ..." bullet, stopping at the first blank line or
 * non-bullet line) from a block of CLI-style text. Blank-line placement
 * differs between real stdout (single newlines) and README's fenced block
 * (a blank line between every line, for Markdown-source readability) --
 * this normalizes both to the same shape so only the actual content is
 * compared.
 */
function extractSections(text) {
  const lines = text.split("\n").map((l) => l.trim())
  const sections = []
  for (const headerRe of SECTION_HEADERS) {
    const headerIdx = lines.findIndex((l) => headerRe.test(l))
    if (headerIdx === -1) {
      sections.push({ header: null, items: [] })
      continue
    }
    const items = []
    for (let i = headerIdx + 1; i < lines.length; i++) {
      const line = lines[i]
      if (line === "") continue
      if (!line.startsWith("-")) break
      items.push(line)
    }
    sections.push({ header: lines[headerIdx], items })
  }
  return sections
}

function renderSections(sections) {
  return sections
    .map(({ header, items }) => [header ?? "(missing)", ...items.map((i) => `  ${i}`)].join("\n"))
    .join("\n\n")
}

function fail(message) {
  process.stderr.write(`\nREADME example drift: ${message}\n`)
  process.stderr.write(
    "The 'See it run' fenced block in README.md no longer matches a fresh run of\n" +
      "examples/application's own doc-generation command. Re-run it yourself\n" +
      "(`cd examples/application && npm run docs`), splice the current\n" +
      "'expiring soon' / 'unconsumed owned variable(s)' output into README.md's\n" +
      "fenced block, and commit both.\n",
  )
  process.exitCode = 1
}

let fresh
try {
  fresh = mkdtempSync(path.join(tmpdir(), "env-cap-readme-example-"))

  // Copy everything except node_modules (symlinked in below, so the example
  // resolves the real, just-installed `env-cap` package.json`.dependencies`
  // reference) and the generated artifacts (regenerated fresh below).
  const EXCLUDED_TOP_LEVEL = new Set(["node_modules", "docs", ".env.example"])
  cpSync(exampleDir, fresh, {
    recursive: true,
    filter: (src) => {
      const rel = path.relative(exampleDir, src)
      if (rel === "") return true
      const [top] = rel.split(path.sep)
      return !EXCLUDED_TOP_LEVEL.has(top)
    },
  })
  // node_modules is excluded above and symlinked back in below (so the copy
  // resolves the real, already-installed `env-cap` package). docs/ and
  // .env.example are excluded since the run below regenerates them fresh
  // anyway (src/generated/ is copied but gets overwritten the same way).
  symlinkSync(path.join(exampleDir, "node_modules"), path.join(fresh, "node_modules"))
  mkdirSync(path.join(fresh, "docs"), { recursive: true })
  mkdirSync(path.join(fresh, "src/generated"), { recursive: true })

  const stdout = execFileSync("npx", ["env-cap", ...CLI_ARGS], {
    cwd: fresh,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  })

  const readme = readFileSync(readmePath, "utf8")
  const fenceMatch = readme.match(/```text\n\$ npx env-cap[\s\S]*?\n```/)
  if (!fenceMatch) {
    fail("could not find the '$ npx env-cap ...' fenced block in README.md at all")
  } else {
    const freshSections = extractSections(stdout)
    const readmeSections = extractSections(fenceMatch[0])
    const freshRendered = renderSections(freshSections)
    const readmeRendered = renderSections(readmeSections)

    if (freshRendered !== readmeRendered) {
      fail(
        `the README's fenced block does not match a fresh run.\n\n` +
          `--- README.md (current) ---\n${readmeRendered}\n\n` +
          `--- fresh run (real) ---\n${freshRendered}\n`,
      )
    } else {
      process.stdout.write(
        "README.md's 'See it run' block matches a fresh examples/application run.\n",
      )
    }
  }
} finally {
  if (fresh) rmSync(fresh, { recursive: true, force: true })
}
